function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function render() {
  const avatarExists = fs.existsSync(path.join(OUT_DIR, AVATAR));

  function channelCard(c) {
    const bannerExists = c.banner && fs.existsSync(path.join(OUT_DIR, c.banner));
    return `<div class="channel">
      <h3 class="channel-name">${escapeHtml(c.name)}</h3>
      <div class="assets-row">
        ${avatarExists ? `<div class="asset-col"><div class="asset-label">Profile picture</div><img class="avatar" src="./${AVATAR}" alt="${escapeHtml(c.name)} avatar"></div>` : '<div class="asset-col missing">avatar missing</div>'}
        ${c.banner ? (bannerExists ? `<div class="asset-col wide"><div class="asset-label">Banner / header</div><img class="banner" src="./${escapeHtml(c.banner)}" alt="${escapeHtml(c.name)} banner"></div>` : '<div class="asset-col missing">banner missing</div>') : ''}
      </div>
      <div class="specs">${escapeHtml(c.specs)}</div>
      <div class="field"><span class="field-label">Display name</span>${escapeHtml(c.displayName)}</div>
      ${c.handle ? `<div class="field"><span class="field-label">Handle / URL</span>${escapeHtml(c.handle)}</div>` : ''}
      <div class="field"><span class="field-label">Bio (${c.bio.length} chars)</span><div class="bio-text">${escapeHtml(c.bio)}</div></div>
      ${c.about ? `<div class="field"><span class="field-label">About (long-form)</span><div class="bio-text">${escapeHtml(c.about).replace(/\n/g, '<br>')}</div></div>` : ''}
    </div>`;
  }

  const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>monomind — Channel Profile Kit</title>
<style>
:root {
  --ivory:#FAF7F0; --ivory-warm:#F5F0E6; --ivory-deep:#EDE8DC;
  --espresso:#2A2318; --espresso-deep:#1a1208; --espresso-mid:#3D3228; --espresso-light:#5C4F3D;
  --gold:#C8A97E; --gold-warm:#D4A84A;
  color-scheme: light dark;
  --bg: var(--espresso-deep); --surface: var(--espresso); --card: var(--espresso-mid);
  --border: var(--espresso-light); --text: var(--ivory); --muted: rgba(250,247,240,0.55); --accent: var(--gold);
}
@media (prefers-color-scheme: light) {
  :root { --bg: var(--ivory); --surface: var(--ivory-warm); --card: #ffffff; --border: var(--ivory-deep); --text: var(--espresso); --muted: #6b5f4d; --accent: #8B6914; }
}
* { box-sizing: border-box; }
body { margin:0; background:var(--bg); color:var(--text); font:15px/1.6 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif; }
header { padding:2.5rem 1.5rem 1rem; max-width:900px; margin:0 auto; }
h1 { margin:0 0 .3rem; font-size:1.7rem; font-weight:300; }
.sub { color:var(--muted); font-size:.85rem; }
main { max-width:900px; margin:0 auto; padding:0 1.5rem 4rem; display:grid; gap:1.4rem; }
.channel { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:1.4rem 1.6rem; }
.channel-name { margin:0 0 .8rem; font-size:1.15rem; font-weight:600; color:var(--accent); }
.assets-row { display:flex; gap:1rem; align-items:flex-start; margin-bottom:.8rem; flex-wrap:wrap; }
.asset-col { flex:0 0 auto; }
.asset-col.wide { flex:1 1 300px; min-width:220px; }
.asset-label { font-size:.68rem; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin-bottom:.3rem; }
.avatar { width:96px; height:96px; border-radius:50%; object-fit:cover; border:1px solid var(--border); }
.banner { width:100%; max-height:150px; object-fit:cover; border-radius:8px; border:1px solid var(--border); }
.missing { color:var(--muted); font-size:.8rem; font-style:italic; padding:1rem; }
.specs { font-size:.72rem; color:var(--muted); margin-bottom:.9rem; font-family:ui-monospace,monospace; }
.field { margin-bottom:.6rem; font-size:.88rem; }
.field-label { display:block; font-size:.68rem; text-transform:uppercase; letter-spacing:.05em; color:var(--accent); margin-bottom:.15rem; }
.bio-text { white-space:pre-wrap; }
</style></head>
<body>
<header>
  <h1>monomind — Channel Profile Kit</h1>
  <div class="sub">Profile picture (shared "monoes" monkey mascot, consistent everywhere), a channel-appropriate banner, and ready-to-paste bio copy sized to each platform's actual limits. Handles marked "suggested" haven't been checked for availability.</div>
</header>
<main>
${CHANNELS.map(channelCard).join('\n')}
</main>
</body></html>`;
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(path.join(OUT_DIR, 'channel-profiles.html'), html);
  console.log(`Wrote channel-profiles.html for ${CHANNELS.length} channels (avatar ${avatarExists ? 'found' : 'MISSING'}) -> ${path.relative(ROOT, OUT_DIR)}`);
}

render();
